function visibleSpan(s){const op=s.attributes['gen_ai.operation.name'];return ['invoke_agent','chat','execute_tool'].includes(op)||(s.scope==='opentelemetry.instrumentation.httpx'&&s.kind==='CLIENT')||(s.kind==='SERVER'&&s.attributes['mcp.method.name']==='tools/call')||!!(s.attributes['db.system']||s.attributes['db.system.name'])||(s.kind==='SERVER'&&!!(s.attributes['http.request.method']||s.attributes['http.method']))}
function nesting(s,all,visible){let parent=all.get(s.parent_span_id),depth=0,seen=new Set();while(parent&&!seen.has(parent.span_id)){seen.add(parent.span_id);if(visible.has(parent.span_id))depth++;parent=all.get(parent.parent_span_id)}return Math.min(depth,6)}

function traceLayout(spans){const shown=spans.filter(s=>visibleSpan(s)&&Number.isFinite(s.start_ns)&&Number.isFinite(s.end_ns)).sort((a,b)=>a.start_ns-b.start_ns),all=new Map(spans.map(s=>[s.span_id,s])),visible=new Set(shown.map(s=>s.span_id));const start=shown.length?Math.min(...shown.map(s=>s.start_ns)):0,end=shown.length?Math.max(...shown.map(s=>s.end_ns)):0;return {shown,all,visible,start,extent:Math.max(1,end-start)}}
function modelBudget(health){const used=health.turns_used,limit=health.daily_turn_limit;if(!Number.isInteger(used)||used<0||!Number.isInteger(limit)||limit<0)return null;const remaining=Math.max(0,limit-used);return {remaining,label:'Live model: '+health.model+' · '+remaining+' of '+limit+' daily turns remaining. Failed attempts count.'}}
if(typeof module!=='undefined')module.exports={visibleSpan,nesting,traceLayout,modelBudget};
